// Verify GitHub HMAC-SHA256 signature.
const crypto = require('crypto');
const sig = $input.first().headers['x-hub-signature-256'];
const secret = $node['SET_DEFAULTS'].json['github_webhook_secret'];
const rawBody = JSON.stringify($input.first().body);

if (!sig || !secret || secret.startsWith('<')) {
  return [{ json: { ok: false, error: 'missing_signature_or_secret' } }];
}
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (sig !== expected) return [{ json: { ok: false, error: 'signature_mismatch' } }];

const event = $input.first().headers['x-github-event'];
const body = $input.first().body;
if (event !== 'pull_request' || !['opened','reopened'].includes(body.action)) {
  return [{ json: { ok: false, error: 'unsupported_event', event, action: body.action } }];
}

return [{ json: { ok: true, pr: body.pull_request, repo: body.repository, sender: body.sender } }];

